package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestTmpStatusAfterWritten(t *testing.T) {
	testWriter := httptest.NewRecorder()
	writer := &responseWriter{}
	writer.reset(testWriter)
	w := ResponseWriter(writer)

	w.WriteHeader(http.StatusOK)
	w.WriteHeaderNow()
	if !w.Written() {
		t.Fatal("expected written")
	}
	w.WriteHeader(http.StatusUnauthorized)
	if got := w.Status(); got != http.StatusOK {
		t.Fatalf("Status() = %d, want %d", got, http.StatusOK)
	}
	if testWriter.Code != http.StatusOK {
		t.Fatalf("recorder code = %d, want 200", testWriter.Code)
	}

	// before the response is written, WriteHeader must still take effect
	w2 := ResponseWriter(&responseWriter{})
	r2 := httptest.NewRecorder()
	w2.(*responseWriter).reset(r2)
	w2.WriteHeader(http.StatusMultipleChoices)
	if got := w2.Status(); got != http.StatusMultipleChoices {
		t.Fatalf("Status() = %d, want 300", got)
	}
	w2.WriteHeaderNow()
	if r2.Code != http.StatusMultipleChoices {
		t.Fatalf("recorder code = %d, want 300", r2.Code)
	}
}

