package gin

import (
	"net/http/httptest"
	"testing"
)

func TestTmpNegotiate(t *testing.T) {
	c, _ := CreateTestContext(httptest.NewRecorder())
	c.Request.Header.Set("Accept", "image/tiff-fx")
	if got := c.NegotiateFormat("image/tiff"); got != "" {
		t.Fatalf("got %q, want empty", got)
	}
	c2, _ := CreateTestContext(httptest.NewRecorder())
	c2.Request.Header.Set("Accept", "image/tiff")
	if got := c2.NegotiateFormat("image/tiff"); got != "image/tiff" {
		t.Fatalf("got %q, want image/tiff", got)
	}
	c3, _ := CreateTestContext(httptest.NewRecorder())
	c3.Request.Header.Set("Accept", "text/html")
	if got := c3.NegotiateFormat("*/*"); got != "*/*" {
		t.Fatalf("got %q", got)
	}
}

